<div class="card"><div class="card-body"><div class="form-grid"><div><span class="sub">Customer</span><h2 id="debit-customer"></h2><small id="debit-meta"></small></div><div class="field"><label>Issue date *</label><input type="date" name="issue_date" value="{{ old('issue_date',now()->format('Y-m-d')) }}" max="{{ now()->format('Y-m-d') }}" required></div><div class="field full"><label>Adjustment reason *</label><textarea name="reason" maxlength="500" required placeholder="Describe the underbilling, price correction, or approved additional charge">{{ old('reason') }}</textarea></div></div></div></div>
<div class="card"><div class="card-head"><h2>Debit note items</h2><button class="btn secondary" type="button" id="add-debit-line">Add item</button></div><div class="table-wrap"><table><thead><tr><th>Description</th><th>Unit</th><th>Qty</th><th>Unit price SAR</th><th></th></tr></thead><tbody id="debit-lines"></tbody></table></div><div class="card-body"><p><strong>VAT rate:</strong> <span id="debit-tax-rate"></span>%</p><div class="form-footer"><button class="btn" type="submit">Post tax debit note</button><a class="btn secondary" href="{{ route('safety-shop.debit-notes.index') }}">Cancel</a></div></div></div></form>
<template id="debit-line-template"><tr><td><input data-name="description" required maxlength="255" placeholder="Adjustment description"></td><td><select data-name="unit"><option value="piece">piece</option><option value="service">service</option><option value="hour">hour</option><option value="set">set</option></select></td><td><input data-name="quantity" type="number" min="0.01" step="0.01" value="1" required></td><td><input data-name="unit_price" type="number" min="0.01" step="0.01" required></td><td><button type="button" class="btn secondary remove-line">Remove</button></td></tr></template>
<script>(()=>{const invoice=document.getElementById('debit-invoice'),lookup=document.getElementById('debit-lookup'),form=document.getElementById('debit-form'),message=document.getElementById('debit-message'),body=document.getElementById('debit-lines'),template=document.getElementById('debit-line-template');let index=0;const add=()=>{const row=template.content.firstElementChild.cloneNode(true);row.querySelectorAll('[data-name]').forEach(el=>el.name=`lines[${index}][${el.dataset.name}]`);row.querySelector('.remove-line').onclick=()=>{if(body.rows.length>1)row.remove();};body.appendChild(row);index++;};add();document.getElementById('add-debit-line').onclick=add;const fail=text=>{message.textContent=text;message.hidden=false;form.hidden=true;};const load=async()=>{const value=invoice.value.trim();if(!value)return fail('Enter the original invoice number.');lookup.disabled=true;try{const response=await fetch(@json(route('safety-shop.debit-notes.lookup'))+'?invoice='+encodeURIComponent(value),{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(response.status===404?'Invoice not found.':'Unable to load the invoice.');const sale=await response.json();document.getElementById('debit-sale-id').value=sale.id;document.getElementById('debit-customer').textContent=sale.customer;document.getElementById('debit-meta').textContent=sale.invoice+' · '+sale.location+' · '+sale.date;document.getElementById('debit-tax-rate').textContent=sale.tax_rate;message.hidden=true;form.hidden=false;}catch(error){fail(error.message);}finally{lookup.disabled=false;}};lookup.onclick=load;invoice.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();load();}});})();</script>
